import java.util.*;
import java.io.*;

public class Main {
    static class Edge {
        int from;
        int to;
        int f;
        int cost;

        Edge() {}

        Edge(int _from, int _to, int _f, int _cost) {
            this.from = _from;
            this.to = _to;
            this.f = _f;
            this.cost = _cost;
        }
    }

    static List<Edge> e = new ArrayList<>();
    static final int N = 1000007;
    static List<Integer>[] g = new ArrayList[N];

    static long totalCost = 0;
    static long[] dist = new long[N];
    static int[] pred = new int[N];
    static int[] pe = new int[N];
    static int[] inq = new int[N];

    static int source = N - 2;
    static int target = N - 1;

    static int n, m, k, c, d;
    static final int timeLayers = 101;

    static int residualCapacity(int x) {
        return e.get(x).to - e.get(x).f;
    }

    static void runDijkstra() {
        for (int i = 0; i < N; i++) {
            dist[i] = Long.MAX_VALUE;
            pred[i] = -1;
            pe[i] = -1;
            inq[i] = 0;
        }
        dist[source] = 0;
        Queue<Integer> q = new LinkedList<>();
        q.offer(source);
        inq[source] = 1;
        while (!q.isEmpty()) {
            int k = q.poll();
            inq[k] = 0;
            for (int edgeIdx : g[k]) {
                if (residualCapacity(edgeIdx) == 0) continue;
                int cst = e.get(edgeIdx).cost;
                int y = e.get(edgeIdx).from;
                if (dist[y] > dist[k] + cst) {
                    dist[y] = dist[k] + cst;
                    pred[y] = k;
                    pe[y] = edgeIdx;
                    if (inq[y] == 0) {
                        inq[y] = 1;
                        q.offer(y);
                    }
                }
            }
        }
    }

    static void augmentFlow() {
        runDijkstra();
        int current = target;
        while (current != source) {
            e.get(pe[current]).f++;
            e.get(pe[current) ^ 1).f--;
            current = pred[current];
        }
        totalCost += dist[target];
    }

    static void addEdge(int x, int y, int capacity, int cost) {
        g[x].add(e.size());
        e.add(new Edge(x, y, 0, cost));
        g[y].add(e.size());
        e.add(new Edge(y, x, capacity, -cost));
    }

    static void buildGraph() {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        m = sc.nextInt();
        k = sc.nextInt();
        c = sc.nextInt();
        d = sc.nextInt();

        for (int i = 0; i < N; i++) {
            g[i] = new ArrayList<>();
        }

        for (int i = 0; i < k; i++) {
            int x = sc.nextInt();
            x--;
            addEdge(source, x, 1, 0);
        }

        for (int i = 0; i < timeLayers; i++) {
            addEdge(i * n, target, k, i * c);
        }

        for (int i = 0; i < m; i++) {
            int x = sc.nextInt();
            int y = sc.nextInt();
            x--;
            y--;
            for (int t = 0; t < timeLayers - 1; t++) {
                for (int j = 0; j < k; j++) {
                    addEdge(x + t * n, y + t * n + n, 1, d * (j * 2 + 1));
                }
            }
            for (int t = 0; t < timeLayers - 1; t++) {
                for (int j = 0; j < k; j++) {
                    addEdge(y + t * n, x + t * n + n, 1, d * (j * 2 + 1));
                }
            }
        }
    }

    static void solve() {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < timeLayers - 1; j++) {
                addEdge(i + j * n, i + j * n + n, k, 0);
            }
        }
        for (int i = 0; i < k; i++) {
            augmentFlow();
        }
        System.out.println(totalCost);
    }

    public static void main(String[] args) {
        buildGraph();
        solve();
    }
}
